exercises.solution:
import math

DOC_VECS = {
    "terms-of-service": [3.0, 2.5, 2.8],
    "reset-password":   [0.9, 0.1, 0.0],
    "track-parcel":     [0.0, 0.2, 0.95],
}

def normalize(v):
    n = math.sqrt(sum(x * x for x in v))
    return [x / n for x in v]

def search(query, k=1):
    q = normalize(query)
    scores = {}
    for doc_id, vec in DOC_VECS.items():
        scores[doc_id] = sum(a * b for a, b in zip(q, normalize(vec)))
    return sorted(scores, key=scores.get, reverse=True)[:k]

print(search([1.0, 0.0, 0.0]))

