exercises.solution:
def embed(text):
    words = [w for w in re.findall(r"[a-z0-9]+", text.lower()) if w in WORD_VECTORS]
    if not words:
        return [0.0] * 6
    dims = len(WORD_VECTORS[words[0]])
    mean = [sum(WORD_VECTORS[w][i] for w in words) / len(words) for i in range(dims)]
    length = math.sqrt(sum(x * x for x in mean))
    return [x / length for x in mean]

def build_index():
    return {doc_id: embed(text) for doc_id, text in DOCS.items()}

def search(query, index, k=3):
    q = embed(query)
    if not any(q):
        return []
    scored = [(doc_id, sum(a * b for a, b in zip(q, vec))) for doc_id, vec in index.items()]
    scored.sort(key=lambda p: (-p[1], p[0]))
    return [doc_id for doc_id, _ in scored[:k]]

def recall_at_1(index):
    hits = sum(1 for q, rel in LABELLED.items() if search(q, index, 1) == [rel])
    return hits / len(LABELLED)


index = build_index()
for q in ["I was charged twice", "parcel lost in delivery", "my screen is broken"]:
    print(q, "->", search(q, index, 2))
print("recall@1 =", recall_at_1(index))

