exercises.solution:
def recall_at_k(results, relevant, k):
    per_query = [len(set(results[q][:k]) & relevant[q]) / len(relevant[q]) for q in relevant]
    return sum(per_query) / len(per_query)

def mrr(results, relevant):
    total = 0.0
    for q, rel in relevant.items():
        for rank, doc in enumerate(results.get(q, []), start=1):
            if doc in rel:
                total += 1 / rank
                break
    return total / len(relevant)


results  = {"q1": ["D5", "D2", "D9", "D1", "D7"], "q2": ["D3", "D4"]}
relevant = {"q1": {"D2", "D7"},                    "q2": {"D3"}}
print(recall_at_k(results, relevant, 3), mrr(results, relevant))
